@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CowListScreen(
    type: String?,
    value: String?,
    onCowClick: (Long) -> Unit,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    val database = CattleDatabase.getDatabase(context)
    val repository = remember {
        CattleRepository(database.cowDao(), database.pastureDao(), database.activityDao(), database.settingsDao())
    }

    // Reuse data already aggregated in ReportsViewModel for filters like breeding, age, etc.
    val reportsViewModel: ReportsViewModel = viewModel(factory = ReportsViewModelFactory(repository))
    val cowsViewModel: CowsViewModel = viewModel(factory = CowsViewModelFactory(repository))

    val allCowsState by reportsViewModel.uiState.collectAsState()

    // Pull full lists from repository for accurate filtering
    val cowsFlow by remember { mutableStateOf(repository.getAllCows()) }
    val activitiesFlow by remember { mutableStateOf(repository.getAllActivities()) }
    val cows by cowsFlow.collectAsState(initial = emptyList())
    val activities by activitiesFlow.collectAsState(initial = emptyList())

    // Build filtered list based on type/value
    val list: List<Cow> = remember(cows, activities, type, value) {
        val active = cows.filter { it.status == Status.ACTIVE }
        when (type) {
            "status" -> {
                when (value) {
                    null -> cows
                    "ACTIVE" -> active
                    "SOLD" -> cows.filter { it.status == Status.SOLD }
                    "DECEASED" -> cows.filter { it.status == Status.DECEASED }
                    else -> active
                }
            }
            "classification" -> active.filter { it.classification.name == value }
            "pasture" -> {
                val pid = value?.toLongOrNull()
                active.filter { it.pastureId == pid }
            }
            "pastureName" -> { // fallback by name: show all with matching pasture name if available via activities? Keep as all active for now
                active
            }
            "notCalved" -> {
                val nineMonthsAgo = java.time.LocalDate.now().minusMonths(9)
                val female = active.filter { it.gender == Gender.FEMALE && it.classification in listOf(Classification.COW, Classification.HEIFER) }
                val calvesInPast9 = cows.filter { it.classification == Classification.CALF && it.birthDate?.isAfter(nineMonthsAgo) == true && it.motherId != null }
                val mothers = calvesInPast9.mapNotNull { it.motherId }.toSet()
                female.filter { it.id !in mothers }
            }
            "calved" -> {
                val nineMonthsAgo = java.time.LocalDate.now().minusMonths(9)
                val calvesInPast9 = cows.filter { it.classification == Classification.CALF && it.birthDate?.isAfter(nineMonthsAgo) == true && it.motherId != null }
                val mothers = calvesInPast9.mapNotNull { it.motherId }.toSet()
                active.filter { it.id in mothers }
            }
            "age" -> filterByAgeGroup(active, value)
            else -> active
        }
    }

    val title = remember(type, value) {
        when (type) {
            "status" -> value ?: "All Cows"
            "classification" -> "${value ?: """}"
            "pasture" -> "Pasture"
            "pastureName" -> value ?: "Pasture"
            "notCalved" -> "Not calved in 9+ months"
            "calved" -> "Calved in past 9 months"
            "age" -> when (value) {
                "UNDER_1" -> "Under 1 year"
                "1_5" -> "1-5 years"
                "5_10" -> "5-10 years"
                "10_PLUS" -> "Over 10 years"
                else -> "By age"
            }
            else -> "Cows"
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(title) },
                navigationIcon = {
                    IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, contentDescription = "Back") }
                }
            )
        }
    ) { padding ->
        if (allCows.isLoading) {
            Box(Modifier.fillMaxSize().padding(padding), contentAlignment = Alignment.Center) {
                CircularProgressIndicator()
            }
        } else {
            LazyColumn(
                modifier = Modifier.fillMaxSize().padding(padding).padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                items(list, key = { it.id }) { cow ->
                    CowCard(cow = cow, onClick = { onCowClick(cow.id) })
                }
            }
        }
    }
}

