@Composable
private fun filterByAgeGroup(active: List<Cow>, value: String?): List<Cow> {
    val today = java.time.LocalDate.now()
    return active.filter { cow ->
        cow.birthDate?.let { bd ->
            val years = java.time.Period.between(bd, today).years
            when (value) {
                "UNDER_1" -> years < 1
                "1_5" -> years in 1..4
                "5_10" -> years in 5..9
                "10_PLUS" -> years >= 10
                else -> true
            }
        } ?: false
    }
}

